+static int
+krb5_frame_compare(gconstpointer a, gconstpointer b)
+{
+	kerberos_frame_t *fa = (kerberos_frame_t *)a;
+	kerberos_frame_t *fb = (kerberos_frame_t *)b;
+
+	return fa->frame - fb->frame;
